INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14201, 'Psalms 79:4', 'Psalms', 79, 4, '&nbsp;مونږ خپلو ګاونډيانو ته سپک ښکارو، او ګېرچاپېره خلق مونږ پورې خاندى او بې‌عزتى مو کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14202, 'Psalms 79:5', 'Psalms', 79, 5, '&nbsp;ترڅو پورې به مالِکه خُدايه؟ تۀ مونږ ته ولې په قهر يې؟ د تل دپاره څۀ؟ ترڅو پورې به ستا غېرت د اور په شان بليږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14203, 'Psalms 79:6', 'Psalms', 79, 6, '&nbsp;خپل غضب دې په هغه قومونو نازل کړه چې تا نۀ پېژنى، هغه بادشاهتونو ته په قهر شه کوم چې دې نوم نۀ اخلى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14204, 'Psalms 79:7', 'Psalms', 79, 7, '&nbsp;ځکه چې هغوئ د يعقوب اولاد لواړ تير کړے دے او مُلک يې ورله په کنډرو بدل کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14205, 'Psalms 79:8', 'Psalms', 79, 8, '&nbsp;مونږ د پلار نيکۀ په ګناه مۀ نيسه، په مونږ دې ستا رحم زر تر زره راشى، ځکه چې مونږ ډېر خوار و زار شوى يُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14206, 'Psalms 79:9', 'Psalms', 79, 9, '&nbsp;زمونږ مدد وکړه، اے زمونږ خلاصونکى پاکه خُدايه، چې ستا نوم جلال ومومى، د خپل نوم په خاطر مونږ ته خلاصون راکړه او زمونږ ګناهونه معاف کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14207, 'Psalms 79:10', 'Psalms', 79, 10, '&nbsp;غېر قومونه دې ولې داسې ووائى چې، ”د دوئ خُدائ پاک چرته دے؟“ زمونږ د سترګو په وړاندې دا قومونه پوهه کړه، چې تا د خپلو خادِمانو د توئ شوې وينې انتقام واخستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14208, 'Psalms 79:11', 'Psalms', 79, 11, '&nbsp;د قېديانو فرياد په خپله واوره، په چا چې د مرګ فېصله شوې ده د خپل مټ په زور دې هغه بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14209, 'Psalms 79:12', 'Psalms', 79, 12, '&nbsp;اے مالِکه خُدايه، تۀ زمونږ ګاونډيانو له اووۀ چنده سزا ورکړه، د هغه سپکوالى په وجه کوم چې دوئ تا پورې کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14210, 'Psalms 79:13', 'Psalms', 79, 13, '&nbsp;نو بيا به مونږ ستا خلق ستا د شپول ګډې به ستا ثناء صِفت د تل دپاره وکړُو، او مونږ به ستا ثناء صِفت د يو نسل نه تر بل نسله پورې جارى ساتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14211, 'Psalms 80:1', 'Psalms', 80, 1, '&nbsp;اے د بنى اِسرائيلو شپونکيه، زمونږ سوال زارى واوره، تا چا چې د يوسف لکه د رمې هسې لارښودنه وکړه، تۀ چې اے خُدايه پاکه پاس په تخت د وزرو والا مخلوق مينځ کښې ناست يې خپل جلال راښکاره کړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14212, 'Psalms 80:2', 'Psalms', 80, 2, '&nbsp;د اِفرائيم، بنيامين او د منسى په وړاندې خپل قدرت دې څرګند کړه. او زمونږ د خلاصون دپاره راشه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14213, 'Psalms 80:3', 'Psalms', 80, 3, '&nbsp;پاکه خُدايه، مونږ دوباره په خپل حال کړه، د خپل مخ رڼا دې په مونږ وځلوه، چې ترڅو مونږ خلاصون حاصل کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14214, 'Psalms 80:4', 'Psalms', 80, 4, '&nbsp;اے مالِکه خُدايه، ربُ الافواج خُدايه ستا غضب به په خپل قوم تر کومې پورې وى، او تۀ به ترڅو پورې د خپلو خلقو دُعاګانې نۀ اورې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14215, 'Psalms 80:5', 'Psalms', 80, 5, '&nbsp;تا د غم په خوراک دوئ ماړۀ کړل، او د اوښکو ډک جام دې په دوئ باندې وڅښلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14216, 'Psalms 80:6', 'Psalms', 80, 6, '&nbsp;تا مونږ د خپلو ګاونډيانو د خندا کړُو، او زمونږ د دشمنانو دې مونږ د مسخرو کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14217, 'Psalms 80:7', 'Psalms', 80, 7, '&nbsp;ربُ الافواج خُدايه، مونږ دوباره په خپل حال کړه، د خپل مخ رڼا دې په مونږ وځلوه، چې ترڅو مونږ خلاصون حاصل کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14218, 'Psalms 80:8', 'Psalms', 80, 8, '&nbsp;تا خپل قوم لکه د انګور د بوټى په شان د مِصر نه راوړلو، او غېر قومونه دې وشړل او د هغوئ په ځائ دې دوئ په خپل مُلک کښې ولګول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14219, 'Psalms 80:9', 'Psalms', 80, 9, '&nbsp;تا د دې دپاره زمکه ښۀ تياره کړه، او جرړې يې وکړې او زمکه يې ډکه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14220, 'Psalms 80:10', 'Psalms', 80, 10, '&nbsp;ټول غرونه د دې په سورى کښې پټ شول، او لوړ او قوى دِيار او هم د انګور څانګې په کښې پټې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14221, 'Psalms 80:11', 'Psalms', 80, 11, '&nbsp;څانګې يې د سمندر پورې خورې شوې، او د فرات د سيند پورې يې ځېلۍ خورې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14222, 'Psalms 80:12', 'Psalms', 80, 12, '&nbsp;تا ولې دېوالونه ورله راوغورزول، د دې دپاره چې څوک په لاره تېريږى انګور ترې راشوکوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14223, 'Psalms 80:13', 'Psalms', 80, 13, '&nbsp;ځنګلى خنزيران دا تباه کوى، او ځنګلى ځناور په کښې څرن کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14224, 'Psalms 80:14', 'Psalms', 80, 14, '&nbsp;اے ربُ الافواج خُدايه، مونږ ته راوګرځه، د آسمان نه لاندې راوګوره، او خپل د انګور بوټے دې وګوره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14225, 'Psalms 80:15', 'Psalms', 80, 15, '&nbsp;هغه جرړه چې ستا ښى لاس لګولې ده، او هغه زوئ چې تا خپل ځان دپاره لوئ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14226, 'Psalms 80:16', 'Psalms', 80, 16, '&nbsp;ستا د انګورو بوټے پرې کړے شوے دے، او اور ته غورزولے شوے دے. او په خپل قهر دې دا خلق تباه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14227, 'Psalms 80:17', 'Psalms', 80, 17, '&nbsp;ستا ښے لاس دې ستا په ښى طرف خلقو باندې وى، د بنى آدم زوئ چې تا خپل ځان دپاره لوئ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14228, 'Psalms 80:18', 'Psalms', 80, 18, '&nbsp;نو داسې به بيا مونږ کله هم تا نه وانۀ وړُو. مونږ ژوندى پرېږده چې ستا د نوم ثناء صِفت وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14229, 'Psalms 80:19', 'Psalms', 80, 19, '&nbsp;اے ربُ الافواج خُدايه، مونږ دوباره په خپل حال کړه، د خپل مخ رڼا دې په مونږ وځلوه، چې ترڅو مونږ خلاصون حاصل کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14230, 'Psalms 81:1', 'Psalms', 81, 1, '&nbsp;خُدائ پاک ته د خوشحالۍ حمدونه ووايئ څوک چې زمونږ زور دے، د يعقوب پاک خُدائ ته سندرې ووايئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14231, 'Psalms 81:2', 'Psalms', 81, 2, '&nbsp;سازونه وغږوئ او تمبل ووهئ، د رباب او سريندې سازونه وغږوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14232, 'Psalms 81:3', 'Psalms', 81, 3, '&nbsp;د نوې مياشتې په ليدو سره بيګل ووهئ، او زمونږ د اختر د ورځې په راتلو سره کله چې سپوږمۍ پوره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14233, 'Psalms 81:4', 'Psalms', 81, 4, '&nbsp;دا د بنى اِسرائيلو دپاره اصُول دے، او د يعقوب د خُدائ پاک قانون دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14234, 'Psalms 81:5', 'Psalms', 81, 5, '&nbsp;هغۀ د يوسف دپاره يو قانون جوړ کړو، چې کله هغه د مِصر په خلاف راووتو. چرته چې مونږ نا آشنا آواز واورېدلو چې پرې نۀ پوهېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14235, 'Psalms 81:6', 'Psalms', 81, 6, '&nbsp;هغه وائى چې، ”ما درله د اوږو نه بوج اخوا کړو، ما ستا لاسونه د دروند بوج نه آزاد کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14236, 'Psalms 81:7', 'Psalms', 81, 7, '&nbsp;تاسو چې په سخته کښې نعرې وکړى نو ما تاسو بچ کړئ، ما درله د تندر د وريځو نه جواب درکړو. کله چې په مريبه کښې اوبۀ نۀ وې ما ستاسو ايمان وآزمائيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14237, 'Psalms 81:8', 'Psalms', 81, 8, '&nbsp;زما غوره شوو خلقو ما ته غوږ ونيسئ تاسو ته خبردارے درکوم، کاش چې تاسو اے بنى اِسرائيلو، ما ته پام وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14238, 'Psalms 81:9', 'Psalms', 81, 9, '&nbsp;ستاسو په مينځ کښې دې غېر معبودان نۀ وى. تاسو چرى هم بل معبود ته سجده ونۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14239, 'Psalms 81:10', 'Psalms', 81, 10, '&nbsp;زۀ مالِک خُدائ، ستاسو خُدائ پاک يم، چا چې تاسو د مِصر نه بهر راوويستئ. خپلې خولې خلاصې کړئ نو زۀ به تاسو له خوراک درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14240, 'Psalms 81:11', 'Psalms', 81, 11, '&nbsp;خو زما خلق به زما خبره نۀ اورى، بنى اِسرائيل به زما تابعدارى نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14241, 'Psalms 81:12', 'Psalms', 81, 12, '&nbsp;نو ځکه ما هغوئ د دوئ د سخت زړۀ عملونو ته حواله کړل، ترڅو چې د خپلو زړونو خواهشونه پوره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14242, 'Psalms 81:13', 'Psalms', 81, 13, '&nbsp;کاش چې زما خلق ما ته غوږ ونيسى، او کۀ چرې بنى اِسرائيل زما په نقش قدم لاړ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14243, 'Psalms 81:14', 'Psalms', 81, 14, '&nbsp;نو څومره زر به بيا ما د دوئ دشمنان تباه کړى وے، او د دوئ د دشمنانو خلاف به ما خپل لاس اوچت کړے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14244, 'Psalms 81:15', 'Psalms', 81, 15, '&nbsp;څوک چې مالِک خُدائ سره کينه لرى د هغۀ په وړاندې به د يرې نه په رپېدو پرېوځى، د هغوئ سزا به د تل دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14245, 'Psalms 81:16', 'Psalms', 81, 16, '&nbsp;خو تاسو ته به د ښو غنمو خوراک درکړم، او تا به د صحرا په شاتو باندې موړ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14246, 'Psalms 82:1', 'Psalms', 82, 1, '&nbsp;خُدائ پاک په خپل آسمانى دربار کښې ولاړ دے، او د نورو معبودانو په مينځ کښې عدالت کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14247, 'Psalms 82:2', 'Psalms', 82, 2, '&nbsp;”ترڅو پورې به تاسو په بې‌اِنصافۍ سره فېصلې کوئ، ترڅو پورې به تاسو د بدکارو طرفدارے کوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14248, 'Psalms 82:3', 'Psalms', 82, 3, '&nbsp;د غريب او د يتيم د حق نه حفاظت وکړئ، او د حاجتمندو او بې‌وسو د حق سره اِنصاف کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14249, 'Psalms 82:4', 'Psalms', 82, 4, '&nbsp;کمزورى او حاجتمند بچ کړئ، او هغوئ د بدعملو د لاسونو نه خلاص کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14250, 'Psalms 82:5', 'Psalms', 82, 5, '&nbsp;ظالمانو ته هيڅ پته نشته او په هيڅ نۀ پوهيږى. دوئ په تيارو کښې ګرځيږى، د زمکې ټول بنيادونه خوځېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14251, 'Psalms 82:6', 'Psalms', 82, 6, '&nbsp;ما وئيل چې، ”تاسو خو خُدايان يئ، تاسو ټول د خُدائ تعالىٰ بچيان يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14252, 'Psalms 82:7', 'Psalms', 82, 7, '&nbsp;خو تاسو به هم د فانى مخلوق په شان مړۀ شئ، تاسو به هم لکه د نورو بادشاهانو راګزار شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14253, 'Psalms 82:8', 'Psalms', 82, 8, '&nbsp;پاکه خُدايه، راپاڅه، د دې زمکې عدالت وکړه، ځکه چې ټول قومونه ستا ميراث دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14254, 'Psalms 83:1', 'Psalms', 83, 1, '&nbsp;پاکه خُدايه چپ مۀ پاتې کېږه، پاکه خُدايه مۀ غلے کېږه مۀ چپ کېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14255, 'Psalms 83:2', 'Psalms', 83, 2, '&nbsp;وګوره ستا دشمنان راپارېدلى دى، او څوک چې تا نه نفرت کوى سرکشۍ سره راپاڅېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14256, 'Psalms 83:3', 'Psalms', 83, 3, '&nbsp;ستا د قوم خلاف يې ارادې د چل نه ډکې دى، تۀ چې چا سره مينه کوې د هغوئ خلاف منصوبې جوړوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14257, 'Psalms 83:4', 'Psalms', 83, 4, '&nbsp;دوئ وائى، ”راځئ چې د يو قوم غوندې يې تباه کړُو، چې د بنى اِسرائيلو نوم په دُنيا کښې نور پاتې نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14258, 'Psalms 83:5', 'Psalms', 83, 5, '&nbsp;په يو سوچ سره دوئ په شريکه منصوبې جوړوى، دوئ ستا خلاف يو موټے شول او اِتحاد جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14259, 'Psalms 83:6', 'Psalms', 83, 6, '&nbsp;په هغوئ کښې دا قومونه شريک وُو ادوميان او اِسمٰعيليان، موآب او هاجريان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14260, 'Psalms 83:7', 'Psalms', 83, 7, '&nbsp;جبل، عمون، عماليقيان، ورسره، صور او فلستيان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14261, 'Psalms 83:8', 'Psalms', 83, 8, '&nbsp;تر دې چې اسوريان ورسره هم يو ځائ شوى دى، او خپل طاقت يې د لوط اولاد سره رايوځائ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14262, 'Psalms 83:9', 'Psalms', 83, 9, '&nbsp;کوم کار دې چې د ميديانيانو سره کړے وو د دوئ سره يې هم وکړه، لکه څنګه چې تا د سِسيرا او د يابين سره د قيسون درياب په غاړه کړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14263, 'Psalms 83:10', 'Psalms', 83, 10, '&nbsp;څوک چې په عين دور کښې تباه شول، او د دوئ د بدن نه د پټو ډيران جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14264, 'Psalms 83:11', 'Psalms', 83, 11, '&nbsp;د هغوئ مشران د عوريب او زئيب په شان مړۀ کړه، او شهزادګان يې لکه د ضلمنع او د زبيح په شان مړۀ کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14265, 'Psalms 83:12', 'Psalms', 83, 12, '&nbsp;دا په کښې چا ووئيل چې، ”راځئ چې د خُدائ پاک د څرن ځايونه قبضه کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14266, 'Psalms 83:13', 'Psalms', 83, 13, '&nbsp;اے پاکه خُدايه زما، هغوئ لکه د خر بوټى په شان سپک کړه، او لکه د بوسو دوئ د باد په وړاندې والوځوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14267, 'Psalms 83:14', 'Psalms', 83, 14, '&nbsp;لکه څنګه چې اور ځنګل سوزوى، او لکه شُغلې چې غرونه لمبه کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14268, 'Psalms 83:15', 'Psalms', 83, 15, '&nbsp;نو په خپل زورَور باد سره دې هغوئ په مخه واخله، او هغوئ په خپل طوفان سره ويروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14269, 'Psalms 83:16', 'Psalms', 83, 16, '&nbsp;تۀ هغوئ په شرمونو وشرموه، نو مالِکه خُدايه، ترڅو چې خلق ستا د نوم لټون وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14270, 'Psalms 83:17', 'Psalms', 83, 17, '&nbsp;هغوئ دې د تل دپاره وشرميږى چې ويريږى. او هغوئ دې د شرم په حالت کښې مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14271, 'Psalms 83:18', 'Psalms', 83, 18, '&nbsp;تۀ هغوئ په دې پوهه کړه چې هغه هم تۀ يې د چا نوم چې مالِک خُدائ دے، او هم دا تۀ يواځې په ټوله زمکه د ټولو نه اوچت خُدائ تعالىٰ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14272, 'Psalms 84:1', 'Psalms', 84, 1, '&nbsp;ستا د اوسېدو ځائ څومره ښکلے دے، اے مالِکه ربُ الافواجه خُدايه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14273, 'Psalms 84:2', 'Psalms', 84, 2, '&nbsp;روح مې ليواله دے تر دې چې ناتوانه دے، د دې دپاره چې زۀ د مالِک خُدائ دربار ته ننوځم. زما زړۀ او زما ځان په چغه د ژوندى خُدائ ثناء صِفت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14274, 'Psalms 84:3', 'Psalms', 84, 3, '&nbsp;چنچڼې خو هم کور پېدا کړے دے، طوطاګرکى خو هم خپل ځان دپاره جاله جوړه کړې ده، ستا د قربان‌ګاه سره نزدې چې خپل بچى په کښې لوئ کړى اے مالِکه خُدايه، ربُ الافواجه زما بادشاه او زما پاکه خُدايه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14275, 'Psalms 84:4', 'Psalms', 84, 4, '&nbsp;بختور دى هغوئ څوک چې ستا کور کښې اوسيږى، دوئ به مدام هلته ستا ثناء صِفت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14276, 'Psalms 84:5', 'Psalms', 84, 5, '&nbsp;بختور دى هغوئ د چا طاقت چې په تا کښې دے، چا چې خپل زړونه د يروشلم سفر پورې تړلى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14277, 'Psalms 84:6', 'Psalms', 84, 6, '&nbsp;کله چې دوئ د بکا وادۍ نه تېريږى، دوئ ترې نه د چينو وادۍ جوړوى. د منې بارانونه په کښې د اوبو تالابونه جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14278, 'Psalms 84:7', 'Psalms', 84, 7, '&nbsp;د دوئ طاقت به په سفر کولو سره نور هم زيات شى، تر دې چې په صيون کښې د خُدائ پاک په وړاندې ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14279, 'Psalms 84:8', 'Psalms', 84, 8, '&nbsp;اے مالِکه ربُ الافواج خُدايه، سوال مې واوره، اے د يعقوب پاکه خُدايه، ما ته غوږ شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14280, 'Psalms 84:9', 'Psalms', 84, 9, '&nbsp;زمونږ پاکه خُدايه، زمونږ په ډال نظر ساته، خپل غوره شوى ته په ښۀ نظر کاتۀ وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14281, 'Psalms 84:10', 'Psalms', 84, 10, '&nbsp;ستا په دربار کښې يوه ورځ بهتره ده په تېرېدو د بل ځائ د زرو ورځو نه. زۀ د خُدائ پاک په کور کښې دربان ښۀ يم نه چې د شريرانو په خېمو کښې اوسېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14282, 'Psalms 84:11', 'Psalms', 84, 11, '&nbsp;خو مالِک خُدائ زمونږ خُدائ پاک نمر او ډال دے. ځکه چې مالِک خُدائ به مونږ ته خپل فضل او عزت راکړى، هغه د هر هغه چا نه ښۀ څيزونه نۀ ايساروى د کومو خلقو لارې چې بې‌داغه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14283, 'Psalms 84:12', 'Psalms', 84, 12, '&nbsp;اے مالِکه خُدايه، ربُ الافواج خُدايه، بختور دے هغه څوک چې په تا توکل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14284, 'Psalms 85:1', 'Psalms', 85, 1, '&nbsp;اے مالِکه خُدايه، تا خپل برکت په خپل مُلک باندې وکړو، او تا دوباره د يعقوب خوش قسمتى بحال کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14285, 'Psalms 85:2', 'Psalms', 85, 2, '&nbsp;تا د خپلو خلقو خطاګانې معاف کړې، تا د هغوئ په ټولو ګناهونه پرده واچوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14286, 'Psalms 85:3', 'Psalms', 85, 3, '&nbsp;تا خپله غصه په خپل ځان تيره کړه، تا د خپل قهر لمبه په خپله باندې سړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14287, 'Psalms 85:4', 'Psalms', 85, 4, '&nbsp;اے مالِکه خُدايه، اے زمونږه خلاصوونکيه، مونږه په خپل ځائ کړه خپل خفګان زمونږ نه لرې کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14288, 'Psalms 85:5', 'Psalms', 85, 5, '&nbsp;تۀ به ټول عُمر زمونږ نه خفه يې څۀ؟ تۀ خپل خفګان نسل در نسل ساتې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14289, 'Psalms 85:6', 'Psalms', 85, 6, '&nbsp;ولې تۀ‎‎‎‎‎‎ به دوباره مونږه تازه نۀ کړې څۀ‎‎‎؟ چې ستا خلق په تا کښې خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14290, 'Psalms 85:7', 'Psalms', 85, 7, '&nbsp;اے مالِکه خُدايه، مونږ ته خپله ابدى مينه وښايه، مونږه له خپل خلاصون راکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14291, 'Psalms 85:8', 'Psalms', 85, 8, '&nbsp;زۀ به مالِک خُدائ، خُدائ پاک ته غوږ ونيسم. ځکه چې هغه به د خپل قوم، خپلو مقدسينو ته وکړى د خير خبره. خو دوئ دوباره خپل کم عقلتوب ته مۀ پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14292, 'Psalms 85:9', 'Psalms', 85, 9, '&nbsp;بې‌شکه چې څوک د خُدائ نه يريږى د هغۀ خلاصون هغۀ ته نزدې دے، نو دغه شان به د هغۀ جلال زمونږ په خاوره کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14293, 'Psalms 85:10', 'Psalms', 85, 10, '&nbsp;ابدى مينه او وفادارى به دواړه خپلو کښې ترغاړه شى، سلامتى او صداقت به يو بل ښُکلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14294, 'Psalms 85:11', 'Psalms', 85, 11, '&nbsp;وفادارى د زمکې نه راپورته کيږى، صداقت بره د آسمان نه لاندې راګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14295, 'Psalms 85:12', 'Psalms', 85, 12, '&nbsp;بې‌شکه مالِک خُدائ به ښۀ څيزونه مونږ له راکوى، او زمونږ زمکه به ښۀ فصل پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14296, 'Psalms 85:13', 'Psalms', 85, 13, '&nbsp;صداقت د هغۀ په وړاندې روان وى، او د هغۀ د قدمونو دپاره لار تياروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14297, 'Psalms 86:1', 'Psalms', 86, 1, '&nbsp;اے مالِکه خُدايه، سوال مې واوره، او قبول يې کړه، ځکه چې زۀ غريب او حاجتمند يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14298, 'Psalms 86:2', 'Psalms', 86, 2, '&nbsp;زما ژوندون وساته ځکه چې ما خپل ځان تا ته پېش کړے دے، هم تۀ زما خُدائ پاک يې خپل خِدمتګار دې بچ کړه چا چې په تا اعتماد کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14299, 'Psalms 86:3', 'Psalms', 86, 3, '&nbsp;په ما رحم وکړه، اے مالِکه خُدايه، ځکه چې زۀ ټوله ورځ تا ته زارى کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14300, 'Psalms 86:4', 'Psalms', 86, 4, '&nbsp;خپل خِدمتګار ته دې خوشحالى ورکړه، ځکه چې ما خپل ځان تا ته وقف کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');